import type { StepRow, StepsPayload } from '../../api/types';
import { Badge } from '../../components/Badge';
import { DataTable } from '../../components/DataTable';
import { Chip, Exhibit } from '../../components/Exhibit';
import { C } from '../../lib/palette';

/**
 * The blinding checklist — generated by the gate, never typed.
 *
 * Iteration 2 re-derives the case from the reads, the VCF and the eight symptoms as if no
 * candidate were known. The candidate gene is written all over this repository, so the
 * blinding cannot be a secret; what makes it checkable is that every methodology entry
 * declares what it read, and `mva-science check --blind` refuses one that names an
 * iteration-1 candidate table before the unblinding entry.
 *
 * This table is that gate's own output. A reader checks the same rows the CI gate checks.
 *
 * `steps` narrows it to the ones the page is about, so a Track 2 iteration page does not
 * list the entries of steps it does not show. The gate's *verdict* is still the whole
 * iteration's, because blinding is a property of the iteration and not of one track.
 */
export function BlindChecklist({
  data,
  steps = data.steps,
}: {
  data: StepsPayload;
  steps?: StepRow[];
}) {
  const rows = steps.flatMap((step) =>
    step.entries.map((entry) => ({
      step: step.slug,
      entry: entry.entry,
      declares: entry.declares_inputs,
      inputs: entry.inputs.length,
      unblinds: entry.unblinds,
      violations: entry.violations.length,
    })),
  );

  return (
    <Exhibit
      title="What each entry says it read"
      legend={
        <>
          One row per methodology entry of this iteration, straight from{' '}
          <code>mva-science check --blind</code>. <Chip color={C.good}>green</Chip> = the entry
          declares its inputs and names nothing it should not have ·{' '}
          <Chip color={C.broken}>red</Chip> = a violation, which fails the gate ·{' '}
          <Chip color={C.decision}>amber</Chip> = the entry that ends the blinding by performing the
          comparison.
        </>
      }
      reading={
        data.blind.still_blind ? (
          <>
            Still blind: no entry has read an iteration-1 candidate table, so nothing this iteration
            has concluded could have come from knowing the answer. The comparison happens once, in
            step 6, and is recorded as its own entry.
          </>
        ) : (
          <>
            Unblinded by <code>{data.blind.unblinded_by}</code>. Entries from that point on may read
            iteration 1&rsquo;s tables — comparing against them is what that entry exists to do.
          </>
        )
      }
    >
      {rows.length === 0 ? (
        <p className="text-xs text-chrome-400">
          No methodology entry has been written for this iteration yet. An iteration with no entries
          is vacuously blind, which is a true statement about it rather than a pass.
        </p>
      ) : (
        <DataTable
          rows={rows}
          rowKey={(row) => `${row.step}/${row.entry}`}
          columns={[
            { key: 'step', header: 'step', render: (row) => row.step },
            { key: 'entry', header: 'entry', render: (row) => row.entry },
            {
              key: 'declares',
              header: 'declares inputs',
              render: (row) =>
                row.declares ? (
                  <Badge tone="good">yes — {row.inputs} rows</Badge>
                ) : (
                  <Badge tone="broken">no</Badge>
                ),
            },
            {
              key: 'violations',
              header: 'gate',
              render: (row) =>
                row.violations > 0 ? (
                  <Badge tone="broken">{row.violations} violation(s)</Badge>
                ) : row.unblinds ? (
                  <Badge tone="decision">unblinds</Badge>
                ) : (
                  <Badge tone="good">clean</Badge>
                ),
            },
          ]}
        />
      )}
    </Exhibit>
  );
}
